        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the `mwifiex` driver retaining the last used random MAC address for all subsequent scan requests, regardless of whether the `NL80211_SCAN_FLAG_RANDOM_ADDR` flag was set. This led to a situation where scans that did not explicitly request a random MAC address still used a previously randomized address, violating the intended behavior of the scanning mechanism.

        Commit message:
        mwifiex: MAC randomization should not be persistent

nl80211 provides the NL80211_SCAN_FLAG_RANDOM_ADDR for every scan
request that should be randomized; the absence of such a flag means we
should not randomize. However, mwifiex was stashing the latest
randomization request and *always* using it for future scans, even those
that didn't set the flag.

Let's zero out the randomization info whenever we get a scan request
without NL80211_SCAN_FLAG_RANDOM_ADDR. I'd prefer to remove
priv->random_mac entirely (and plumb the randomization MAC properly
through the call sequence), but the spaghetti is a little difficult to
unravel here for me.

Fixes: c2a8f0ff9c6c ("mwifiex: support random MAC address for scanning")
Cc: <stable@vger.kernel.org> # 4.9+
Signed-off-by: Brian Norris <briannorris@chromium.org>
Signed-off-by: Kalle Valo <kvalo@codeaurora.org>  

        Patch:
          */
 static int
 mwifiex_cfg80211_scan(struct wiphy *wiphy,
 		      struct cfg80211_scan_request *request)
 {
 	struct net_device *dev = request->wdev->netdev;
 	struct mwifiex_private *priv = mwifiex_netdev_get_priv(dev);
 	int i, offset, ret;
 	struct ieee80211_channel *chan;
 	struct ieee_types_header *ie;
 	struct mwifiex_user_scan_cfg *user_scan_cfg;

 	mwifiex_dbg(priv->adapter, CMD,
 		    "info: received scan request on %s\n", dev->name);

 	/* Block scan request if scan operation or scan cleanup when interface
 	 * is disabled is in process
 	 */
 	if (priv->scan_request || priv->scan_aborting) {
 		mwifiex_dbg(priv->adapter, WARN,
 			    "cmd: Scan already in process..\n");
 		return -EBUSY;
 	}

 	if (!priv->wdev.current_bss && priv->scan_block)
 		priv->scan_block = false;

 	if (!mwifiex_stop_bg_scan(priv))
 		cfg80211_sched_scan_stopped_rtnl(priv->wdev.wiphy);

 	user_scan_cfg = kzalloc(sizeof(*user_scan_cfg), GFP_KERNEL);
 	if (!user_scan_cfg)
 		return -ENOMEM;

 	priv->scan_request = request;

 	if (request->flags & NL80211_SCAN_FLAG_RANDOM_ADDR) {
 		ether_addr_copy(priv->random_mac, request->mac_addr);
 		for (i = 0; i < ETH_ALEN; i++) {
 			priv->random_mac[i] &= request->mac_addr_mask[i];
 			priv->random_mac[i] |= get_random_int() &
 					       ~(request->mac_addr_mask[i]);
 		}
+		ether_addr_copy(user_scan_cfg->random_mac, priv->random_mac);
+	} else {
+		eth_zero_addr(priv->random_mac);
 	}

-	ether_addr_copy(user_scan_cfg->random_mac, priv->random_mac);
 	user_scan_cfg->num_ssids = request->n_ssids;
 	user_scan_cfg->ssid_list = request->ssids;

 	if (request->ie && request->ie_len) {
 		offset = 0;
 		for (i = 0; i < MWIFIEX_MAX_VSIE_NUM; i++) {
 			if (priv->vs_ie[i].mask != MWIFIEX_VSIE_MASK_CLEAR)
 				continue;
 			priv->vs_ie[i].mask = MWIFIEX_VSIE_MASK_SCAN;
 			ie = (struct ieee_types_header *)(request->ie + offset);
 			memcpy(&priv->vs_ie[i].ie, ie, sizeof(*ie) + ie->len);
 			offset += sizeof(*ie) + ie->len;

 			if (offset >= request->ie_len)
 				break;
 		}
 	}

 	for (i = 0; i < min_t(u32, request->n_channels,
 			      MWIFIEX_USER_SCAN_CHAN_MAX); i++) {
 		chan = request->channels[i];
 		user_scan_cfg->chan_list[i].chan_number = chan->hw_value;
 		user_scan_cfg->chan_list[i].radio_type = chan->band;

 		if ((chan->flags & IEEE80211_CHAN_NO_IR) || !request->n_ssids)
 			user_scan_cfg->chan_list[i].scan_type =
 						MWIFIEX_SCAN_TYPE_PASSIVE;
 		else
 			user_scan_cfg->chan_list[i].scan_type =
 						MWIFIEX_SCAN_TYPE_ACTIVE;

 		user_scan_cfg->chan_list[i].scan_time = 0;
 	}

 	if (priv->adapter->scan_chan_gap_enabled &&
 	    mwifiex_is_any_intf_active(priv))
 		user_scan_cfg->scan_chan_gap =
 					      priv->adapter->scan_chan_gap_time;

 	ret = mwifiex_scan_networks(priv, user_scan_cfg);
 	kfree(user_scan_cfg);
 	if (ret) {
 		mwifiex_dbg(priv->adapter, ERROR,
 			    "scan failed: %d\n", ret);
 		priv->scan_aborting = false;
 		priv->scan_request = NULL;
 		return ret;
 	}

 	if (request->ie && request->ie_len) {
 		for (i = 0; i < MWIFIEX_MAX_VSIE_NUM; i++) {
 			if (priv->vs_ie[i].mask == MWIFIEX_VSIE_MASK_SCAN) {
 				priv->vs_ie[i].mask = MWIFIEX_VSIE_MASK_CLEAR;
 				memset(&priv->vs_ie[i].ie, 0,
 				       MWIFIEX_MAX_VSIE_LEN);
 			}
 		}
 	}
 	return 0;
 }



